import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d as p,i as P,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"VXLAN 与覆盖网","description":"","frontmatter":{"title":"VXLAN 与覆盖网","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vxlan-overlay.md","filePath":"cs/vxlan-overlay.md","lastUpdated":1789023840000}'),c={name:"cs/vxlan-overlay.md"};function h(V,a,E,A,N,_){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="vxlan-与覆盖网" tabindex="-1">VXLAN 与覆盖网 <a class="header-anchor" href="#vxlan-与覆盖网" aria-label="Permalink to &quot;VXLAN 与覆盖网&quot;">​</a></h1><div class="epigraph"><p>租户以太网帧装进 UDP，外层 IP 在 Clos 上 ECMP；VNI 隔离广播域，底层不必再为每个租户拉 VLAN。</p><footer>—— 据 RFC 7348 VXLAN；数据中心网络实践整理</footer></div><p><a href="/cs/ecmp-hashing">上一课</a> 要熵。大二层 <a href="/cs/mac-learning">MAC 学习</a> 洪泛在数万口上爆炸。缺口是<strong>覆盖网</strong>：VXLAN 把 L2 帧 UDP 封装，VTEP 之间只跑 IP。本课不把 EVPN 控制面写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VLAN 12 比特不够租户；STP 大域收敛差。VXLAN：24 比特 VNI，外层 UDP 目的 4789，源端口哈希内层流——把熵交给底层 ECMP。数据面仍可能未知单播洪泛（BUM），除非控制面（下一课 EVPN）分发 MAC。覆盖不提高 \\(C\\)，只改拓扑：物理是 L3 Clos，逻辑是 L2 段。</p><p>不要把 VXLAN 写成加密：那是 IPsec/MACSec 另加。</p><p><span class="marginnote">RFC 7348 是信息性封装。实现差异在控制面。本课钉数据面。</span></p><h3 id="封装不提高" tabindex="-1">封装不提高 \\(C\\) <a class="header-anchor" href="#封装不提高" aria-label="Permalink to &quot;封装不提高 $C$&quot;">​</a></h3><p>VNI 隔离，UDP 源端口带熵。BUM 仍可能复制，除非 EVPN。底层 MTU 必须吃外层头。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：VM MAC → VTEP 封装 → 底层 IP/ECMP → 对端 VTEP 解封装。对照 VLAN tag：tag 在同一广播域里走；VXLAN 跨 IP 网。MTU：外层头约 50 字节，接住巨帧课，要底层更大或分片。</p>',11)),(e(),n(d,null,{default:r(()=>[P(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L2%5B%22%E7%A7%9F%E6%88%B7%E4%BB%A5%E5%A4%AA%E7%BD%91%E5%B8%A7%22%5D%20--%3E%20ENC%5B%22VXLAN%2BUDP%2BIP%22%5D%0A%20%20ENC%20--%3E%20UND%5B%22%E5%BA%95%E5%B1%82%20ECMP%22%5D%0A%20%20UND%20--%3E%20DEC%5B%22VTEP%20%E8%A7%A3%E5%B0%81%E8%A3%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 MPLS VPN 对照：都是外层隧道 + 内层上下文（VNI vs 内层标签）。SR/GRE 可当另一种外层。PFC/RoCE 在覆盖下更难：外层丢包与内层无损语义冲突，后课 RoCE 会收回。</p><p>BUM：复制到所有 VTEP 或用底层组播；组播后课。无控制面时学习靠洪泛与源学习，像大号以太网。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Geneve 的 TLV 灵活性全文。EVPN 是下一课。后课默认：VXLAN 是 L2overL3 数据面；洪泛要靠控制面收敛。</p><p>硬件 VTEP 与软件 VTEP 性能差在 PPS，不在 RFC 格式。</p><p>上一课留下的缺口在本课收口；「VXLAN 与覆盖网」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/evpn">EVPN</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VNI 隔离；UDP 源端口带熵。</li><li>底层 L3 ECMP，逻辑 L2。</li><li>封装吃 MTU；BUM 是覆盖的痛。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7348。</li></ul>',10))])}const T=o(c,[["render",h]]);export{m as __pageData,T as default};
